import{z as s,x as E,o as a,c,q as d,j as l,D as o,d as p,s as t,S as i}from"./chunks/framework.C8m1ZpeB.js";const h=JSON.parse('{"title":"CUTLASS Grouped GEMM","description":"","frontmatter":{"title":"CUTLASS Grouped GEMM","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/cutlass-grouped-gemm.md","filePath":"llm/cutlass-grouped-gemm.md","lastUpdated":1791413859000}'),n={name:"llm/cutlass-grouped-gemm.md"};function M(u,e,A,m,B,g){const r=E("Mermaid");return a(),c("div",null,[e[2]||(e[2]=d('<h1 id="cutlass-grouped-gemm" tabindex="-1">CUTLASS Grouped GEMM <a class="header-anchor" href="#cutlass-grouped-gemm" aria-label="Permalink to &quot;CUTLASS Grouped GEMM&quot;">​</a></h1><div class="epigraph"><p>Grouped GEMM 计算一批问题尺寸可以各不相同的 GEMM；全局内存里的矩阵指针、leading dimension 与问题尺寸都以数组传入。这与要求各批形状相同的 batched array GEMM 不同。</p><footer>—— NVIDIA CUTLASS，`examples/24_gemm_grouped/gemm_grouped.cu`</footer></div><p>MoE 专家侧的标准乘法是：\\(E\\) 个问题共享相近的 \\(N,K\\)（FFN 宽），只有 \\(M_i\\)（该专家分到的 token 数）不同。<code>cublasGemmBatched</code> 一类接口要求所有 batch 同形状，于是实现要么 pad 到 \\(\\max M_i\\)，要么循环 \\(E\\) 次启动。CUTLASS 的 grouped GEMM 把「不同 \\((M_i,N_i,K_i)\\)」收成 <strong>一次持久化核</strong>：线程块少于总瓦片数，由 problem visitor 按 round-robin 领取下一个瓦片。MegaBlocks 的 dropless 路径在软件层证明这件事能训；CUTLASS 提供的是可在 Ampere / Hopper / Blackwell 上特化的工业实现。Blackwell 上 cuDNN 还把块缩放、门控乘与量化 epilogue 融进 <code>BlockScaledMoEGroupedGemmQuantKernel</code>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>一次启动的开销在 decode 和小 \\(M_i\\) 时特别刺眼：256 个专家、每个 \\(M_i\\lt 64\\)，循环启动会让 GPU 空转在 launch 上。Pad 到同一 \\(M\\) 则把 FLOPs 和 HBM 流量付给空行，热专家本来就决定墙钟，padding 让冷专家也占瓦片。需要的原语是：设备侧看见一组问题描述，自己决定下一张瓦片属于哪个专家、瓦片在该问题内的坐标。</p><p>调度还有第二种不均：即使 \\(M_i\\) 相同，某些问题的 \\(K\\) 或对齐不同。通用 grouped 接口因此允许每个问题独立的尺寸与指针。MoE 只用到这个接口的一个切片——变 \\(M\\)、共享 \\(N,K\\)、权重指针按专家 stride。</p><h3 id="持久化核与普通网格的差别" tabindex="-1">持久化核与普通网格的差别 <a class="header-anchor" href="#持久化核与普通网格的差别" aria-label="Permalink to &quot;持久化核与普通网格的差别&quot;">​</a></h3><p>常规 GEMM 的网格大小等于瓦片数，一个线程块算一个瓦片然后退出。Grouped 核通常启动 <strong>少于总瓦片</strong> 的线程块，每个块用 visitor 循环领取工作。这样做的原因是问题列表在运行时才知道，且小问题若各占一个块，占用率碎片化。持久化还让调度可以在设备上做前缀和，而不必每次 host 同步。</p><p><span class="marginnote">CUTLASS 文档把 grouped 核称为 persistent kernel。<code>GroupScheduleMode::kDeviceOnly</code> 在 GPU 上扫问题数组；<code>kHostPrecompute</code> 在 host 算好「块 → 瓦片」表写入 workspace，核内 \\(O(1)\\) 查找。Decode 每步 \\(M_i\\) 都变，host 预计算可能比核本身还贵。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>设备接口（历史 API 里的 <code>GemmGrouped</code> / <code>BaseGrouped</code>）管理 workspace、可选的 host 侧预计算、以及 kernel launch。问题数组在 GMEM：每个问题有 <code>GemmCoord(M,N,K)</code>、A/B/C 指针、LDA/LDB/LDC。示例程序 <code>24_gemm_grouped</code> 会随机生成一组尺寸，并与「按尺寸分桶再跑常规 batched GEMM」对照，用来说明专用 grouped 核的收益。</p><p><span class="marginnote">「瓦片」就是把大矩阵切成的小方块，比如 \\(128\\times128\\) 的一小块，刚好喂给 Tensor Core 一次算完。「线程块领取瓦片」可以想象成几十个工人（线程块）守在一条传送带（瓦片队列）边取活干：活的总数开工前数不清，所以工人干完一件再取下一件，而不是每人预先分好固定一件。</span></p><p>Visitor 的基本步进：线程块持有一个 <code>tile_idx</code>，初值为 <code>blockIdx.x</code>，每做完一块加 <code>gridDim.x</code>。给定全局瓦片号，要回答：它属于哪个问题、是该问题的哪一块。这需要对各问题的瓦片数做前缀和。<code>kDeviceOnly</code> 让每块自己扫；问题数到几百（DeepSeek 量级）时，扫的开销要靠实现优化，不能假设是零。<code>kHostPrecompute</code> 把前缀和放到启动前，适合预填 \\(M_i\\) 暂时稳定、同一图要跑多次的情况。</p>',13)),(a(),l(i,null,{default:o(()=>[t(r,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20PROB%5B%22GMEM%20%E9%97%AE%E9%A2%98%E6%95%B0%E7%BB%84%20M_i%2CN_i%2CK_i%22%5D%20--%3E%20MODE%7B%22%E8%B0%83%E5%BA%A6%E6%A8%A1%E5%BC%8F%22%7D%0A%20%20MODE%20--%3E%20DEV%5B%22kDeviceOnly%3A%20%E5%9D%97%E5%86%85%20next_tile%22%5D%0A%20%20MODE%20--%3E%20HOST%5B%22kHostPrecompute%3A%20workspace%20%E6%9F%A5%E6%89%BE%22%5D%0A%20%20DEV%20--%3E%20MMA%5B%22%E7%93%A6%E7%89%87%20MMA%22%5D%0A%20%20HOST%20--%3E%20MMA%0A%20%20MMA%20--%3E%20EPI%5B%22Epilogue%20%2F%20%E9%97%A8%E6%8E%A7%20%2F%20%E9%87%8F%E5%8C%96%22%5D%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[p(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=d('<h3 id="sm100-上的-moe-融合核" tabindex="-1">SM100 上的 MoE 融合核 <a class="header-anchor" href="#sm100-上的-moe-融合核" aria-label="Permalink to &quot;SM100 上的 MoE 融合核&quot;">​</a></h3><p>cuDNN Frontend 为 Blackwell 提供统一的 grouped GEMM + 量化融合：块缩放（FP4 / FP8）、按行门控乘、可选的输出量化尺度。<code>MoEWeightMode.DENSE</code> 与 <code>DISCRETE</code> 区分权重布局。文档约束包括：专家数 \\(\\le 1024\\)，\\(M\\) 对齐到 256，需要 <code>prob_tensor</code>（无门控时传全 1），A/B 同 dtype。这是把 MegaBlocks 式 grouped 乘与 NVFP4 微缩放、V3 式门控乘焊在同一 epilogue 里，避免「先 GEMM 再逐元素」的往返。FC2（下投影）与反向的 dFC1 是文档点名的用法。</p><p><span class="marginnote">「epilogue（收尾段）」指矩阵乘主循环结束后对输出小块做的额外处理：乘门控系数、按块缩放、量化打包。初学者容易以为这些是独立的 kernel；实际上每多一次往返，都要把中间结果整块写回显存再读回来——\\(M=N=4096\\) 的中间矩阵一次往返就是几十 MB 的 HBM 流量，焊进 epilogue 后这笔账直接消失。</span></p><p>未到 SM100 时，Hopper 的 grouped 核仍是 MoE 训练 / 预填的主力；decode 小 \\(M\\) 可能要另写 GEMV 友好的路径，因为 Tensor Core 瓦片填不满。CUTLASS 的 grouped scheduler 文档还讨论了按问题顺序领取导致的负载不均，以及把大问题的瓦片打散给更多块的变体。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>Round-robin 瓦片分配近似于：总工作量按瓦片数均分。热专家 \\(M_h\\gg M_c\\)，它占的瓦片多，自然分到更多块-迭代。这比「一块绑定一个专家直到做完」更能填满 SM。极端情况下一个专家占了 90% 瓦片，grouped 核也救不了跨卡 EP 的热度——那是 EPLB 的问题。Grouped GEMM 只均衡 <strong>一张卡内</strong> 多个本地专家之间的 SM。</p>',6)),(a(),l(i,null,{default:o(()=>[t(r,{id:"mermaid-56",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22256%20%E4%B8%AA%E4%B8%93%E5%AE%B6%20M_i%20%E5%90%84%E4%B8%8D%E7%9B%B8%E5%90%8C%22%5D%20--%3E%20A%5B%22%E6%96%B9%E6%A1%88%E4%B8%80%20pad%20%E5%88%B0%20max%20M_i%22%5D%0A%20%20Q%20--%3E%20B%5B%22%E6%96%B9%E6%A1%88%E4%BA%8C%20%E5%BE%AA%E7%8E%AF%E5%90%AF%E5%8A%A8%20E%20%E6%AC%A1%E5%B0%8F%E6%A0%B8%22%5D%0A%20%20Q%20--%3E%20C%5B%22%E6%96%B9%E6%A1%88%E4%B8%89%20grouped%20%E4%B8%80%E6%AC%A1%E5%90%AF%E5%8A%A8%22%5D%0A%20%20A%20--%3E%20W1%5B%22%E5%86%B7%E4%B8%93%E5%AE%B6%E4%B9%9F%E4%BB%98%20FLOPs%20%E4%B8%8E%20HBM%20%E6%B5%81%E9%87%8F%22%5D%0A%20%20B%20--%3E%20W2%5B%22GPU%20%E7%A9%BA%E8%BD%AC%E5%9C%A8%20launch%20%E5%BC%80%E9%94%80%E4%B8%8A%22%5D%0A%20%20C%20--%3E%20V%5B%22visitor%20round-robin%20%E9%A2%86%E7%93%A6%E7%89%87%22%5D%0A%20%20V%20--%3E%20S%5B%22SM%20%E6%8C%89%E7%93%A6%E7%89%87%E6%95%B0%E8%87%AA%E7%84%B6%E5%A1%AB%E6%BB%A1%22%5D%0A"})]),fallback:o(()=>[...e[1]||(e[1]=[p(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=d('<p><span class="marginnote">round-robin（轮转）可以想象成银行叫号：柜台数量固定（线程块少于瓦片数），号（瓦片）按顺序发放。热专家票号多，自然占更多柜台时间；冷专家几张票干完就走。这正是「按瓦片数均分工作量」这个说法的直觉来源，也是它优于「一块绑死一个专家」的原因。</span></p><p>指针数组使权重可以不紧挨着。EP 下本卡只有 \\(N/E\\) 个专家，数组长度是本地专家数，不是全局 \\(N\\)。逻辑专家到物理槽位的映射变了（EPLB 搬家），只要改指针表，不必重编译核。这是 grouped 接口相对「一个大张量切块」布局的灵活性。</p><p><span class="marginnote">Batched GEMM 是 grouped 的特例：所有 \\(M_i\\) 相等。CUTLASS 示例允许用命令行把 M/N/K 固定，用来对照。评测 MoE 时不要用固定 \\(M\\) 的 grouped 数字去代表真实路由后的变 \\(M\\)；不均才是 grouped 要打的那一仗。</span></p><h3 id="与-megablocks、triton、cublas-的分工" tabindex="-1">与 MegaBlocks、Triton、cublas 的分工 <a class="header-anchor" href="#与-megablocks、triton、cublas-的分工" aria-label="Permalink to &quot;与 MegaBlocks、Triton、cublas 的分工&quot;">​</a></h3><p>MegaBlocks 论文的块稀疏核是 dropless 的算法论证；其库的 <code>grouped</code> 实现往往直接调这类 grouped GEMM。Triton 也能写循环专家的核，但持久化 visitor、跨问题的瓦片调度要自己写，Hopper / Blackwell 的 MMA 流水更难对齐。cuBLAS 的 batched 接口不覆盖变 \\(M\\)。工程选择通常是：训练与预填走 CUTLASS / cuDNN grouped；decode 极小 \\(M\\) 走特化 GEMV 或把专家复制后改数据并行。不要强迫所有工作点共用一个 grouped 配置。</p><p>Workspace：<code>kHostPrecompute</code> 要一份与网格相关的表；融合核还要块尺度张量（SFA/SFB）的 6D 布局。这些字节要进显存账，尤其 NVFP4 的 scale 本身不是免费的。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>对齐约束是静默坑。SM100 文档写 \\(M\\) 对齐 256，真实 \\(M_i=17\\) 必须 pad 到对齐或走另一套核。Pad 只发生在瓦片边缘，仍比 Switch 式容量因子轻，但「完全 dropless、零 padding」在有对齐的 MMA 上不成立。应在实现里把对齐 padding 与容量掉牌分开记账。</p><p>Host 同步：每步从 CPU 填写问题数组会导致 GPU 空等。应在 device 上由直方图核直接写 <code>M_i</code> 与指针，grouped 核随后启动，中间用 event，而不是 D2H/H2D。CUDA Graph 要固定网格与问题槽位数：空专家保留 \\(M_i=0\\) 的槽。</p><p>专家数上限、dtype 组合、是否支持按问题不同的 \\(N,K\\)，都以当前 CUTLASS / cuDNN 版本为准。抄一篇 2022 年 example 24 的 Sm80 配置到 Blackwell 上，不会自动变成第五代 MMA。</p><p><span class="marginnote">出处：NVIDIA CUTLASS <code>examples/24_gemm_grouped</code>；<em>Grouped Kernel Schedulers</em> 文档（<code>GroupScheduleMode</code>、problem visitor）；cuDNN Frontend <em>Grouped GEMM + Quant – Unified (SM100)</em>。算法背景见 Gale et al. MegaBlocks，arXiv:2211.15841。</span></p><p>不要把 grouped GEMM 当成 All-to-All。它发生在 dispatch 之后、combine 之前，是本地计算。通信再快，这里若启动了 256 次小核，decode TPOT 一样坏。反过来，grouped 核再快，热专家卡上的 \\(M_i\\) 仍决定 EP 的步时。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>CUTLASS grouped GEMM 一次启动计算不同形状的一组 GEMM，是 MoE 变 \\(M_i\\) 的硬件接口。</li><li>持久化 visitor 按瓦片 round-robin 领取工作；调度可在 device 或 host 预计算。</li><li>相对 batched GEMM，省的是 padding 与多次 launch；相对循环专家，省的是启动开销。</li><li>SM100 融合核把块缩放、门控与量化 epilogue 焊进同一路径，服务 NVFP4 MoE。</li><li>对齐、\\(M_i=0\\)、host 同步和卡内热专家仍是边界；跨卡均衡交给 EPLB。</li><li>出处：NVIDIA CUTLASS grouped 示例与调度文档；cuDNN SM100 grouped+quant；Gale et al.，MLSys 2023。</li></ul>',14))])}const S=s(n,[["render",M]]);export{h as __pageData,S as default};
